def f(g, dir_):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    cells={(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==4}
    six=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==6]
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==4: out[r][c]=4
    # draw mirror
    b=max(r for r,_ in cells)
    if dir_=='down':
        for t in range(b+1,min(H,b+1+len(cells))):
            rr=b-(t-(b+1))
            for (r_,c_) in cells:
                if r_==rr: out[t][c_]=4
    elif dir_=='up':
        for t in range(max(0,b-len(cells)+1),b):
            rr=b+len(cells)-1-t
            for (r_,c_) in cells:
                if r_==rr: out[t][c_]=4
    elif dir_=='left':
        cmin=min(c for _,c in cells)
        for t in range(cmin-1,max(-1,cmin-len(cells))+1):
            cc=cmin-(t-(-1))-cmin+... 
            pass
    return out
