                if any(a<0 or a>=H or b<0 or b>=W for a,b in cells) or cells&S: continue
                clear=min(abs(a-c)+abs(b-d) for a,b in cells for c,d in six)
                cands.append((clear,sorted(cells)))
    best=min(cands)[1]
    o=[[0]*W for _ in range(H)]
    for r,c in S: o[r][c]=4
    for r,c in six: o[r][c]=0
    for r,c in best: o[r][c]=4
    return o
